async function git(args: string[], signal: AbortSignal): Promise<string> {
  const { stdout } = await execFileAsync('git', args, { cwd: process.cwd(), signal, encoding: 'utf8', maxBuffer: 16 * 1024 * 1024 })
  return stdout.trim()
}

async function gateBase(signal: AbortSignal): Promise<{ base?: string; baseSha: string; root: string }> {
  const root = await git(['rev-parse', '--show-toplevel'], signal)
  try {
    const base = await git(['rev-parse', '--abbrev-ref', '--symbolic-full-name', '@{upstream}'], signal)
    const baseSha = await git(['rev-parse', base], signal)
    return { base, baseSha, root }
  } catch {
    const baseSha = await git(['rev-parse', 'HEAD'], signal)
    return { baseSha, root }
  }
}

async function isAncestor(ancestor: string, head: string, signal: AbortSignal): Promise<boolean> {
  try {
    await git(['merge-base', '--is-ancestor', ancestor, head], signal)
    return true
  } catch {
    return false
  }
}

function gitPushCommand(arguments_: unknown): boolean {
  if (!arguments_ || typeof arguments_ !== 'object') return false
  const command = (arguments_ as { command?: unknown }).command
  if (typeof command !== 'string') return false
  return /(?:^|[;&|]\s*)\s*(?:\w+=\S+\s+)*git(?:\s+(?:-C\s+\S+|-c\s+\S+|--git-dir(?:=\S+|\s+\S+)|--work-tree(?:=\S+|\s+\S+)))*\s+push(?:\s|$)/.test(command)
}

function openFindings(episode: GateEpisode): GateFinding[] {
  return episode.findings.filter(finding => finding.status === 'open')
}

function feedback(episode: GateEpisode, mode: 'discovery' | 'verification', human: boolean): string {
  const open = openFindings(episode)
  return JSON.stringify({
    kind: human ? 'jury_gate_human_required' : 'jury_gate_blocked',
    episodeId: episode.episodeId,
    baseSha: episode.baseSha,
    round: episode.round,
    mode,
    remaining: open.length,
    message: human ? '请人工裁决' : mode === 'discovery' ? '发现模式：请修复冻结的 findings 后重试' : '验收模式：仍有未清零 findings',
    findings: open.map(finding => ({
      id: finding.id,
      file: finding.file,
      line: finding.line,
      severity: finding.severity,
      title: finding.title,
      fix: finding.fix,
    })),
  }, null, 2)
}

function isAcceptanceOutput(value: unknown): value is { checks: AcceptanceCheck[] } {
  return !!value && typeof value === 'object' && Array.isArray((value as { checks?: unknown }).checks)
    && (value as { checks: AcceptanceCheck[] }).checks.every(check => typeof check.id === 'string'
      && (check.status === 'fixed' || check.status === 'open') && typeof check.reason === 'string')
}

async function acceptDiff(
  ctx: Context,
  config: JuryConfig,
  parent: Agent,
  episode: GateEpisode,
  diff: string,
  signal: AbortSignal,
): Promise<AcceptanceCheck[]> {
  const frozen = episode.findings.map(({ id, file, line, title, fix }) => ({ id, file, line, title, fix }))
  const prompt = `You are a lightweight acceptance agent, not a reviewer. Compare the new diff only with the frozen finding set F. For every id in F, decide fixed when the new diff resolves that exact issue and open otherwise. Return every id once with a short reason. Do not report new problems, do not add findings, do not use tools, and do not return prose outside the structured result.\nFrozen F:\n${JSON.stringify(frozen, null, 2)}\nNew diff:\n${diff}`
  const activation = await ctx.subagents.startActivation({
    provider: 'spawn',
    label: `jury-acceptance-${episode.round + 1}`,
    request: {
      prompt: [{ type: 'text', text: prompt }],
      parent,
      outputSchema: acceptanceSchema,
      agentOptions: { maxTokens: config.agentMaxTokens },
      maxDepth: 1,
    },
    signal,
    delivery: 'caller',
  })
  const result = await activation.result
  if (result.stopReason !== 'completed' || !isAcceptanceOutput(result.structured)) {
    throw new Error(`acceptance failed: ${result.stopReason}`)
  }
  const known = new Set(episode.findings.map(finding => finding.id))
  return result.structured.checks.filter(check => known.has(check.id))
}

