    const token = tokens[index]
    if (token === '--base') {
      base = tokens[index + 1]
      if (!base) throw new Error(usage())
      index += 1
    } else if (token?.startsWith('--base=')) {
      base = token.slice('--base='.length)
    } else if (token === '--tier' || token?.startsWith('--tier=')) {
